import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry layernorm_forward(
    .param .u64 x_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .s32 norm_size,
    .param .f32 epsilon
)
{
    .reg .pred %p<16>;
    .reg .u32 %r<32>;
    .reg .u64 %rd<32>;
    .reg .f32 %f<64>;

    .shared .align 4 .f32 reduce_area[1024];
    .shared .align 4 .f32 mean_slot;
    .shared .align 4 .f32 inv_slot;

    ld.param.u64 %rd0, [x_ptr];
    ld.param.u64 %rd1, [weight_ptr];
    ld.param.u64 %rd2, [bias_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.s32 %r0, [norm_size];
    ld.param.f32 %f0, [epsilon];

    mov.u32 %r1, %ntid.x;
    mov.u32 %r2, %tid.x;
    mov.u32 %r3, %ctaid.x;

    cvt.u64.u32 %rd6, %r3;
    cvt.u64.s32 %rd7, %r0;
    mul.lo.u64 %rd6, %rd6, %rd7;
    shl.b64 %rd6, %rd6, 2;
    add.u64 %rd4, %rd0, %rd6;
    add.u64 %rd5, %rd3, %rd6;

    shr.u32 %r4, %r0, 2;
    shl.b32 %r5, %r4, 2;
    and.b32 %r6, %r0, 3;
    setp.ne.s32 %p0, %r6, 0;
    @%p0 mov.u32 %r4, 0;
    @%p0 mov.u32 %r5, 0;

    and.b64 %rd6, %rd4, 15;
    and.b64 %rd7, %rd1, 15;
    or.b64 %rd6, %rd6, %rd7;
    and.b64 %rd7, %rd2, 15;
    or.b64 %rd6, %rd6, %rd7;
    and.b64 %rd7, %rd5, 15;
    or.b64 %rd6, %rd6, %rd7;
    setp.ne.u64 %p1, %rd6, 0;
    @%p1 mov.u32 %r4, 0;
    @%p1 mov.u32 %r5, 0;

    mov.f32 %f1, 0f00000000;
