            "layernorm_finalize",
            grid=(rows, 1, 1),
            block=(128, 1, 1),
            arguments=[
                partial,
                mean_buf,
                inv_buf,
                i32(self._norm_size),
                i32(chunks),
                f32(float(self.ln.eps)),
            ],
            shared_memory=0,
            stream=stream,
        )
        norm_block = 256
        norm_grid = max(1, min((total // 4 + norm_block - 1) // norm_block, 2048))
        module.launch(
            "layernorm_forward",
            grid=(norm_grid, 1, 1),
            block=(norm_block, 1, 1),
            arguments=[
                x,
                self.ln.weight,
                self.ln.bias,
                output,
                mean_buf,
                inv_buf,
                i32(self._norm_size),
                i32(total),
            ],
            shared_memory=0,
            stream=stream,
        )
        return output
